import http.server as h, functools as f
class H(h.SimpleHTTPRequestHandler):
    def end_headers(self):
        self.send_header('Cache-Control', 'no-store')  # always serve the newest files
        super().end_headers()
h.ThreadingHTTPServer(('', 8611), f.partial(H, directory='slides')).serve_forever()
